import java.awt.geom.*;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.*;
import static java.lang.Math.*;

public class B {
    static class SCC {
        private boolean[] used;
        private List<Integer> finished;
        List<Integer>[] g;
        List<Integer>[] rg;
        int[] cmp;
        int[] cmpSize;

        public SCC(List<Integer>[] g, List<Integer>[] rg) {
            int n = g.length;
            this.g = g;
            this.rg = rg;
            used = new boolean[n];
            finished = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                dfs(i);
            }
            used = new boolean[n];
            int group = 0;
            cmp = new int[n];
            cmpSize = new int[n];
            for (int i = n - 1; i >= 0; i--) {
                if (used[finished.get(i)]) continue;
                rdfs(finished.get(i), group++);
            }
        }

        void dfs(int u) {
            used[u] = true;
            for (int v : g[u]) {
                if (used[v]) continue;
                dfs(v);
            }
            finished.add(u);
        }

        void rdfs(int u, int group) {
            used[u] = true;
            cmp[u] = group;
            cmpSize[group]++;
            for (int nbr : rg[u]) {
                if (used[nbr]) continue;
                rdfs(nbr, group);
            }
        }
    }

    int dfs(int cur) {
        int r = scc.cmpSize[scc.cmp[cur]]==1?1:0;
        visited[cur] = true;
        for (int nbr:g[cur]) {
            if (visited[nbr]) continue;
            r &= dfs(nbr);
        }
        for (int nbr:rg[cur]) {
            if (visited[nbr]) continue;
            r &= dfs(nbr);
        }
        return r;
    }

    List<Integer>[] g;
    List<Integer>[] rg;
    SCC scc;
    boolean[] visited;

    public B() throws Exception {
        int n = in.nextInt();
        int m = in.nextInt();
        g = new List[n];
        rg = new List[n];
        for (int i=0; i<n; i++) g[i] = new ArrayList<>();
        for (int i=0; i<n; i++) rg[i] = new ArrayList<>();
        for (int i=0; i<m; i++) {
            int a = in.nextInt()-1;
            int b = in.nextInt()-1;
            g[a].add(b);
            rg[b].add(a);
        }

        scc = new SCC(g, rg);
        int ans = n;
        visited = new boolean[n];
        for (int i=0; i<n; i++) {
            if (visited[i]) continue;
            ans -= dfs(i);
        }

        buf.append(ans).append('\n');
    }

